func TestFilesService_Add(t *testing.T) {
	t.Parallel()

	client := newTestClient(t, func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			t.Fatalf("unexpected method: %s", r.Method)
		}
		if r.URL.Path != "/files" {
			t.Fatalf("unexpected path: %s", r.URL.Path)
		}
		if got := r.Header.Get("Content-Type"); !strings.HasPrefix(got, "multipart/form-data; boundary=") {
			t.Fatalf("unexpected content type: %q", got)
		}
		if err := r.ParseMultipartForm(1 << 20); err != nil {
			t.Fatalf("parse multipart form: %v", err)
		}
		part := r.MultipartForm.File["file"]
		if len(part) != 1 {
			t.Fatalf("expected one file part, got %d", len(part))
		}
		if got := part[0].Filename; got != "upload.txt" {
			t.Fatalf("unexpected file name: %q", got)
		}
		f, err := part[0].Open()
		if err != nil {
			t.Fatalf("open file part: %v", err)
		}
		defer f.Close()
		content, err := io.ReadAll(f)
		if err != nil {
			t.Fatalf("read file part: %v", err)
		}
		if got := string(content); got != "file content" {
			t.Fatalf("unexpected file content: %q", got)
		}

		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{"success":true,"data":{"id":12,"name":"upload.txt"}}`))
	})

	file, err := client.Files.Add(context.Background(), "upload.txt", strings.NewReader("file content"))
	if err != nil {
		t.Fatalf("Add error: %v", err)
	}
	if file.ID != 12 || file.Name != "upload.txt" {
		t.Fatalf("unexpected file: %#v", file)
	}
}

