package multipartbody

import (
	"io"
	"mime"
	"mime/multipart"
	"net/http"
	"net/url"
	"strings"
	"testing"
)

func readPart(t *testing.T, contentType string, body io.Reader, fieldName string) (*multipart.Part, string) {
	t.Helper()

	mediaType, params, err := mime.ParseMediaType(contentType)
	if err != nil {
		t.Fatalf("parse content type: %v", err)
	}
	if !strings.HasPrefix(mediaType, "multipart/form-data") {
		t.Fatalf("unexpected media type: %q", mediaType)
	}

	reader := multipart.NewReader(body, params["boundary"])
	for {
		part, err := reader.NextPart()
		if err == io.EOF {
			break
		}
		if err != nil {
			t.Fatalf("next part: %v", err)
		}
		if part.FormName() != fieldName {
			continue
		}
		data, err := io.ReadAll(part)
		if err != nil {
			t.Fatalf("read part: %v", err)
		}
		return part, string(data)
	}
	t.Fatalf("part %q not found", fieldName)
	return nil, ""
}

func TestNewFile(t *testing.T) {
	t.Parallel()

	contentType, body, err := NewFile("file", "upload.txt", strings.NewReader("file content"))
	if err != nil {
		t.Fatalf("NewFile error: %v", err)
	}

	// A *bytes.Reader gives http.NewRequest a working GetBody, so requests
	// built from it can be replayed by the retry transport.
	req, err := http.NewRequest(http.MethodPost, "https://example.test", body)
	if err != nil {
		t.Fatalf("build request: %v", err)
	}
	if req.GetBody == nil {
		t.Fatalf("expected request GetBody to be set")
	}

	part, content := readPart(t, contentType, body, "file")
	if got := part.FileName(); got != "upload.txt" {
		t.Fatalf("unexpected file name: %q", got)
	}
	if content != "file content" {
		t.Fatalf("unexpected file content: %q", content)
	}
}

func TestNewFileWithFields(t *testing.T) {
	t.Parallel()

	fields := url.Values{}
	fields.Set("deal_id", "7")
	fields.Set("lead_id", "adf21080-0e10-11eb-879b-05d71fb426ec")

	contentType, body, err := NewFileWithFields("file", "upload.txt", fields, strings.NewReader("file content"))
	if err != nil {
		t.Fatalf("NewFileWithFields error: %v", err)
	}

	part, content := readPart(t, contentType, body, "file")
	if got := part.FileName(); got != "upload.txt" {
		t.Fatalf("unexpected file name: %q", got)
	}
	if content != "file content" {
		t.Fatalf("unexpected file content: %q", content)
	}

	if _, got := readPart(t, contentType, body, "deal_id"); got != "7" {
		t.Fatalf("unexpected deal_id: %q", got)
	}
	if _, got := readPart(t, contentType, body, "lead_id"); got != "adf21080-0e10-11eb-879b-05d71fb426ec" {
		t.Fatalf("unexpected lead_id: %q", got)
	}
}

func TestNewFile_ValidatesInput(t *testing.T) {
	t.Parallel()

	if _, _, err := NewFile("", "upload.txt", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty field name")
	}
	if _, _, err := NewFile("file", "", strings.NewReader("x")); err == nil {
		t.Fatalf("expected error for empty file name")
	}
	if _, _, err := NewFile("file", "upload.txt", nil); err == nil {
		t.Fatalf("expected error for nil content")
	}
}

