package v1

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"strconv"
	"strings"

	"github.com/juhokoskela/pipedrive-go/internal/multipartbody"
	"github.com/juhokoskela/pipedrive-go/pipedrive"
)

type File struct {
	ID          FileID          `json:"id,omitempty"`
	Name        string          `json:"name,omitempty"`
	FileName    string          `json:"file_name,omitempty"`
	FileType    string          `json:"file_type,omitempty"`
	FileSize    int             `json:"file_size,omitempty"`
	Description string          `json:"description,omitempty"`
	URL         string          `json:"url,omitempty"`
	UserID      *UserID         `json:"user_id,omitempty"`
	DealID      *DealID         `json:"deal_id,omitempty"`
	PersonID    *PersonID       `json:"person_id,omitempty"`
	OrgID       *OrganizationID `json:"org_id,omitempty"`
	ProductID   *ProductID      `json:"product_id,omitempty"`
	ActivityID  *ActivityID     `json:"activity_id,omitempty"`
	LeadID      *LeadID         `json:"lead_id,omitempty"`
	Active      bool            `json:"active_flag,omitempty"`
	Inline      bool            `json:"inline_flag,omitempty"`
	AddTime     *DateTime       `json:"add_time,omitempty"`
	UpdateTime  *DateTime       `json:"update_time,omitempty"`
}

type FilesService struct {
	client *Client
}

type FilesOption interface {
	applyFiles(*filesOptions)
}

type filesOptions struct {
	query          url.Values
	fields         url.Values
	requestOptions []pipedrive.RequestOption
}

type filesOptionFunc func(*filesOptions)

func (f filesOptionFunc) applyFiles(cfg *filesOptions) {
	f(cfg)
}

func WithFilesQuery(values url.Values) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.query = mergeQueryValues(cfg.query, values)
	})
}

func WithFilesRequestOptions(opts ...pipedrive.RequestOption) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		cfg.requestOptions = append(cfg.requestOptions, opts...)
	})
}

// withFileField sets a multipart form field sent alongside the file by Add.
func withFileField(key, value string) FilesOption {
	return filesOptionFunc(func(cfg *filesOptions) {
		if cfg.fields == nil {
			cfg.fields = url.Values{}
		}
		cfg.fields.Set(key, value)
	})
}

// WithFileDealID associates the uploaded file with a deal.
func WithFileDealID(id DealID) FilesOption {
	return withFileField("deal_id", strconv.FormatInt(int64(id), 10))
}

// WithFilePersonID associates the uploaded file with a person.
func WithFilePersonID(id PersonID) FilesOption {
	return withFileField("person_id", strconv.FormatInt(int64(id), 10))
}

// WithFileOrganizationID associates the uploaded file with an organization.
func WithFileOrganizationID(id OrganizationID) FilesOption {
	return withFileField("org_id", strconv.FormatInt(int64(id), 10))
}

// WithFileProductID associates the uploaded file with a product.
func WithFileProductID(id ProductID) FilesOption {
	return withFileField("product_id", strconv.FormatInt(int64(id), 10))
}

// WithFileActivityID associates the uploaded file with an activity.
func WithFileActivityID(id ActivityID) FilesOption {
	return withFileField("activity_id", strconv.FormatInt(int64(id), 10))
}

// WithFileLeadID associates the uploaded file with a lead.
func WithFileLeadID(id LeadID) FilesOption {
	return withFileField("lead_id", string(id))
}

// WithFileProjectID associates the uploaded file with a project.
func WithFileProjectID(id ProjectID) FilesOption {
	return withFileField("project_id", strconv.FormatInt(int64(id), 10))
}

func newFilesOptions(opts []FilesOption) filesOptions {
	var cfg filesOptions
	for _, opt := range opts {
		if opt == nil {
			continue
		}
		opt.applyFiles(&cfg)
	}
	return cfg
}

func (s *FilesService) List(ctx context.Context, opts ...FilesOption) ([]File, *Pagination, error) {
	cfg := newFilesOptions(opts)

	var payload struct {
		Data           []File `json:"data"`
		AdditionalData *struct {
			Pagination *Pagination `json:"pagination"`
		} `json:"additional_data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, "/files", cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, nil, err
	}
	var page *Pagination
	if payload.AdditionalData != nil {
		page = payload.AdditionalData.Pagination
	}
	return payload.Data, page, nil
}

func (s *FilesService) Get(ctx context.Context, id FileID, opts ...FilesOption) (*File, error) {
	if err := validateID(id, "file id"); err != nil {
		return nil, err
	}
	cfg := newFilesOptions(opts)
	path := fmt.Sprintf("/files/%d", id)

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodGet, path, cfg.query, nil, &payload, cfg.requestOptions...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

// Add uploads a single file from content, sent as the "file" part of a
// multipart/form-data body. Use the WithFile*ID options to associate the
// file with a deal, person, organization, product, activity, lead or
// project.
//
// The multipart body is buffered before sending, so the request gets a
// working GetBody and the retry transport can replay the upload after
// 429/5xx responses even when content is not seekable (e.g. an *os.File).
func (s *FilesService) Add(ctx context.Context, fileName string, content io.Reader, opts ...FilesOption) (*File, error) {
	cfg := newFilesOptions(opts)
	if fileName == "" || content == nil {
		return nil, fmt.Errorf("file name and content are required")
	}

	contentType, body, err := multipartbody.NewFileWithFields("file", fileName, cfg.fields, content)
	if err != nil {
		return nil, err
	}

	reqOpts := append([]pipedrive.RequestOption{}, cfg.requestOptions...)
	reqOpts = append(reqOpts, pipedrive.WithHeader("Content-Type", contentType))

	var payload struct {
		Data *File `json:"data"`
	}
	if err := s.client.Raw.Do(ctx, http.MethodPost, "/files", cfg.query, body, &payload, reqOpts...); err != nil {
		return nil, err
	}
	if payload.Data == nil {
		return nil, fmt.Errorf("missing file data in response")
	}
	return payload.Data, nil
}

